-- IWT item seed from IWT_Inventory_Master (applied 2026-10-22). Safe to re-run: skips existing SKUs.
-- Unconfirmed rows load ACTIVE with needs_confirm set (shown under Inventory → To confirm).
update public.items set sku = 'MED-CRB', category = 'Media', strategy = 'warehouse', active = true, needs_confirm = 'Confirm type/unit'
 where sku is null and name ilike 'carbon media%';
